/*
	CommonSendMapper.insertSmsEvent
*/
INSERT INTO SMSCLI_TBL_EVENT(
	TRAN_PHONE, TRAN_CALLBACK, TRAN_STATUS, TRAN_DATE, TRAN_MSG, B_MSG_KEY, RESERVED3
) VALUES (
	#{tranPhone}, #{tranCallback}, #{tranStatus},


		#{tranDate}


		${tranDate}


	, CAST(#{tranMsg} AS VARCHAR(2000)), #{bMsgKey}, #{reserved3}
)

/*
	CommonSendMapper.insertLmsEvent
*/
INSERT INTO LMSCLI_TBL_EVENT(
	TRAN_PHONE, TRAN_CALLBACK, TRAN_STATUS, TRAN_DATE, TRAN_TITLE, TRAN_MSG, B_MSG_KEY, RESERVED3
) VALUES (
	#{tranPhone}, #{tranCallback}, #{tranStatus}, 


		#{tranDate}


		${tranDate}


	, #{tranTitle}, CAST(#{tranMsg} AS VARCHAR(2000)), #{bMsgKey}, #{reserved3}
)

/*
	CommonSendMapper.insertMmsEvent
*/
INSERT INTO MMSCLI_TBL_EVENT (
	TRAN_PHONE, TRAN_CALLBACK, TRAN_STATUS, TRAN_DATE, TRAN_TITLE, TRAN_MSG, B_MSG_KEY, RESERVED3, IMAGE_PATH_01, IMAGE_PATH_02, IMAGE_PATH_03
) VALUES (
	#{tranPhone}, #{tranCallback}, #{tranStatus}, 


		#{tranDate}


		${tranDate}


	,  #{tranTitle}, CAST(#{tranMsg} AS VARCHAR(2000)), #{bMsgKey}, #{reserved3}, #{imagePath01}, #{imagePath02}, #{imagePath03}
)
